const data = $('AI Response Cleaner').first().json;
const job = data.job_data || {};
function hasArabic(text) { return /[\u0600-\u06FF]/.test(String(text || '')); }
function cleanList(values) { return (values || []).map(v => String(v).trim()).filter(Boolean); }
function isSocial(job, skills) { const text = [job.title, job.jd_text, skills.join(' ')].join(' ').toLowerCase(); return /social|content|meta ads|facebook|instagram|tiktok|reels|copywriting|analytics/.test(text); }
function arPost(job, skills) {
  const title = job.title || '\u0627\u0644\u062f\u0648\u0631 \u0627\u0644\u0645\u0637\u0644\u0648\u0628';
  const location = job.location || '\u064a\u062a\u0645 \u062a\u062d\u062f\u064a\u062f\u0647 \u0644\u0627\u062d\u0642\u0627';
  const workType = job.employment_type || '\u064a\u062a\u0645 \u062a\u062d\u062f\u064a\u062f\u0647 \u0644\u0627\u062d\u0642\u0627';
  const exp = job.min_experience != null ? String(job.min_experience) + '+ \u0633\u0646\u0629 \u062e\u0628\u0631\u0629' : '\u062e\u0628\u0631\u0629 \u0645\u0646\u0627\u0633\u0628\u0629 \u0644\u0644\u062f\u0648\u0631';
  const deadline = job.deadline ? '\u0642\u0628\u0644 ' + job.deadline : '\u0641\u064a \u0623\u0642\u0631\u0628 \u0648\u0642\u062a';
  const social = isSocial(job, skills);
  const rows = [];
  rows.push(social ? ('\u0645\u0637\u0644\u0648\u0628 ' + title + ' \u064a\u0641\u0647\u0645 \u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0648\u0627\u0644\u0623\u0631\u0642\u0627\u0645\u060c \u0645\u0634 \u0646\u0634\u0631 \u0628\u0648\u0633\u062a\u0627\u062a \u0648\u062e\u0644\u0627\u0635') : ('\u0645\u0637\u0644\u0648\u0628 ' + title + ' \u064a\u0639\u0631\u0641 \u064a\u0645\u0633\u0643 \u0627\u0644\u062f\u0648\u0631 \u0645\u0646 \u0623\u0648\u0644 \u064a\u0648\u0645'));
  rows.push('', '\u0627\u0644\u0645\u0633\u0624\u0648\u0644\u064a\u0627\u062a:');
  const resp = social ? [
    '\u062a\u062c\u0647\u064a\u0632 content calendar \u0648\u0627\u0636\u062d \u0648\u0645\u0646\u0627\u0633\u0628 \u0644\u0643\u0644 \u0645\u0646\u0635\u0629',
    '\u0643\u062a\u0627\u0628\u0629 captions \u0648\u0623\u0641\u0643\u0627\u0631 \u0645\u062d\u062a\u0648\u0649 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0646\u0634\u0631',
    '\u0645\u062a\u0627\u0628\u0639\u0629 \u0623\u062f\u0627\u0621 \u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0648\u0627\u0644\u062d\u0645\u0644\u0627\u062a \u0648\u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0644\u062a\u062d\u0633\u064a\u0646\u0627\u062a',
    '\u062a\u0646\u0633\u064a\u0642 \u0627\u0644\u0634\u063a\u0644 \u0645\u0639 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0623\u0648 \u0627\u0644\u062a\u0635\u0648\u064a\u0631 \u0644\u0636\u0645\u0627\u0646 \u062e\u0631\u0648\u062c \u0645\u062d\u062a\u0648\u0649 \u0642\u0648\u064a'
  ] : [
    '\u062a\u0646\u0641\u064a\u0630 \u0645\u0647\u0627\u0645 ' + title + ' \u0627\u0644\u064a\u0648\u0645\u064a\u0629 \u0628\u0648\u0636\u0648\u062d',
    '\u0645\u062a\u0627\u0628\u0639\u0629 \u0627\u0644\u0646\u062a\u0627\u0626\u062c \u0648\u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u0623\u062f\u0627\u0621',
    '\u0627\u0644\u062a\u0639\u0627\u0648\u0646 \u0645\u0639 \u0627\u0644\u0641\u0631\u064a\u0642 \u0644\u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0644\u062e\u0637\u0629 \u062a\u0646\u0641\u064a\u0630'
  ];
  resp.forEach(x => rows.push('- ' + x));
  rows.push('', '\u0627\u0644\u0645\u062a\u0637\u0644\u0628\u0627\u062a:', '- ' + exp);
  skills.forEach(skill => rows.push('- ' + skill));
  rows.push('', '\u0645\u0648\u0642\u0639 \u0627\u0644\u0639\u0645\u0644: ' + location, '\u0646\u0648\u0639 \u0627\u0644\u0639\u0645\u0644: ' + workType, '', '\u0642\u062f\u0645 \u0627\u0644\u0622\u0646 ' + deadline + ':', '[FORM_LINK]');
  return rows.join('\n');
}
function enPost(job, skills) {
  const title = job.title || 'the role';
  const location = job.location || 'To be confirmed';
  const workType = job.employment_type || 'To be confirmed';
  const exp = job.min_experience != null ? String(job.min_experience) + '+ years of experience' : 'Relevant experience';
  const deadline = job.deadline ? 'before ' + job.deadline : 'as soon as possible';
  const social = isSocial(job, skills);
  const rows = [social ? title + ' needed for content that performs, not just posts that fill a calendar' : title + ' needed to own the role from day one', '', 'Responsibilities:'];
  (social ? ['Build and manage a practical content calendar','Write captions and content ideas for each platform','Track content/campaign performance and turn insights into improvements','Coordinate with design or production to publish strong assets'] : ['Own the day-to-day execution for the role','Track results and improve performance continuously','Work with the team to turn objectives into practical action']).forEach(x => rows.push('- ' + x));
  rows.push('', 'Requirements:', '- ' + exp);
  skills.forEach(skill => rows.push('- ' + skill));
  rows.push('', 'Location: ' + location, 'Work type: ' + workType, '', 'Apply ' + deadline + ':', '[FORM_LINK]');
  return rows.join('\n');
}
function isWeakPost(post) {
  const text = String(post || '');
  if (!text.includes('[FORM_LINK]')) return true;
  if (!text.includes('\n- ') && !text.includes('Responsibilities:') && !text.includes('Requirements:')) return true;
  return false;
}
const skills = cleanList(job.required_skills);
const combinedText = [job.title, job.department, job.jd_text, skills.join(' ')].join(' ');
const formattedPost = hasArabic(combinedText) ? arPost(job, skills) : enPost(job, skills);
const jobPost = isWeakPost(data.job_post) ? formattedPost : data.job_post;
return [{ json: { job_data: job, job_post: jobPost } }];

const googleResponse = $input.first().json;
const jobData = $('Extract Job Data').first().json.job_data;

const timestamp = Date.now();
const random = Math.floor(Math.random() * 1000).toString().padStart(3, '0');
const jobId = `JOB_${timestamp}_${random}`;

return [{
  json: {
    job_id:          jobId,
    title:           jobData.title,
    department:      jobData.department || '',
    jd_text:         jobData.jd_text,
    required_skills: (jobData.required_skills || []).join('; '),
    min_experience:  jobData.min_experience || 0,
    min_score:       jobData.min_score || 70,
    form_link:       googleResponse.formLink,
    status:          'Open',
    deadline:        jobData.deadline || '',
    created_at:      new Date().toISOString(),
    form_id:         googleResponse.formId
  }
}];

