const raw = String($input.first().json.output || '').trim();
const clean = raw.replace(/```json/gi, '').replace(/```/g, '').trim();

function hasJsonShape(text) {
  return text.includes('{') && text.includes('}');
}

function extractJson(text) {
  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');
  if (first === -1 || last === -1 || last <= first) return text;
  return text.slice(first, last + 1);
}

function pick(obj, ...keys) {
  for (const key of keys) {
    if (obj && Object.prototype.hasOwnProperty.call(obj, key)) return obj[key];
  }
  return undefined;
}

function asArray(value) {
  if (Array.isArray(value)) return value.map(String).map(s => s.trim()).filter(Boolean);
  if (value == null || value === '') return [];
  return String(value)
    .split(new RegExp('[;,\\n\\u060C]+'))
    .map(s => s.trim())
    .filter(Boolean);
}

function normalizeQuestion(q) {
  if (typeof q === 'string') return { title: q, type: 'short_answer', required: true };
  return {
    title: String(pick(q, 'title', 'question', 'text') || '').trim(),
    type: pick(q, 'type') || 'short_answer',
    ...(Array.isArray(q.options) ? { options: q.options } : {}),
    required: pick(q, 'required') !== false,
  };
}

let parsed;
try {
  parsed = JSON.parse(hasJsonShape(clean) ? extractJson(clean) : clean);
} catch (e) {
  // Normal conversational answers from the agent are questions for HR, not errors.
  return [{
    json: {
      type: 'question',
      message: clean
    }
  }];
}

if (parsed.ask_hr) {
  return [{ json: { type: 'question', message: String(parsed.ask_hr) } }];
}

const sourceJob = pick(parsed, 'job_data', 'jobdata', 'jobData');
const jobPost = String(pick(parsed, 'job_post', 'jobpost', 'jobPost') || '').split('[FORMLINK]').join('[FORM_LINK]');

if (!sourceJob || !jobPost) {
  return [{
    json: {
      type: 'question',
      message: clean
    }
  }];
}

const customQuestionsRaw = pick(sourceJob, 'custom_questions', 'customquestions', 'customQuestions');
const jobData = {
  title: pick(sourceJob, 'title') || '',
  department: pick(sourceJob, 'department') ?? null,
  required_skills: asArray(pick(sourceJob, 'required_skills', 'requiredskills', 'requiredSkills')),
  min_experience: pick(sourceJob, 'min_experience', 'minexperience', 'minExperience') ?? null,
  min_score: pick(sourceJob, 'min_score', 'minscore', 'minScore') ?? null,
  salary_range: pick(sourceJob, 'salary_range', 'salaryrange', 'salaryRange') ?? null,
  location: pick(sourceJob, 'location') ?? null,
  employment_type: pick(sourceJob, 'employment_type', 'employmenttype', 'employmentType') ?? null,
  deadline: pick(sourceJob, 'deadline') ?? null,
  jd_text: pick(sourceJob, 'jd_text', 'jdtext', 'jdText') || '',
  custom_questions: Array.isArray(customQuestionsRaw)
    ? customQuestionsRaw.map(normalizeQuestion).filter(q => q.title)
    : [],
};

return [{
  json: {
    type: 'job',
    job_data: jobData,
    job_post: jobPost
  }
}];
